async function runWithLimit(items, limit, worker) {
  const results = [];
  let i = 0;
  const runners = Array.from({ length: limit }, async () => {
    while (i < items.length) results.push(await worker(items[i++ ]));
  });
  await Promise.all(runners);
  return results;
}

